ruleSearch.bookList:
@js:(function(){
var out=[];var seen={};
var re=/<a[^>]*href="(\/cn\/comics\/(\d+))"[^>]*>[\s\S]*?<img[^>]*src="([^"]+)"[^>]*alt="([^"]*)"[^>]*>/g;
var m;
while((m=re.exec(result))){
  if(seen[m[2]])continue;seen[m[2]]=1;
  var cover=m[3];if(cover.indexOf('biccam.com/comics/')<0)continue;
  out.push({name:(m[4]||'').trim()||m[2],bookUrl:'https://mycomic.com'+m[1],coverUrl:cover});
}
return out;})()

ruleToc.chapterList:
@js:(function(){
var out=[];
var m=result.match(/chapters:\s*(\[[\s\S]*?\])/);
if(m){
  try{
    var list=JSON.parse(m[1]);
    for(var i=0;i<list.length;i++){
      out.push({name:String(list[i].title),url:'https://mycomic.com/cn/chapters/'+list[i].id});
    }
    return out;
  }catch(e){}
}
var re=/<a[^>]*href="[^"]*\/cn\/chapters\/(\d+)"[^>]*>([\s\S]*?)<\/a>/g;
var m2;
while((m2=re.exec(result))){
  var t=m2[2].replace(/<[^>]+>/g,'').trim();
  if(t)out.push({name:t,url:'https://mycomic.com/cn/chapters/'+m2[1]});
}
return out;})()

ruleContent.content:
@js:(function(){
var out=[];var seen={};
var re=/<(?:img|amp-img)[^>]*class="[^"]*page[^"]*"[^>]*>/g;
var m;
function handle(tag){
  var src=(tag.match(/data-src="([^"]+)"/)||[])[1]||(tag.match(/src="([^"]+)"/)||[])[1]||'';
  if(src.indexOf('biccam.com/chapters/')>=0&&!seen[src]){seen[src]=1;out.push('<img src="'+src+'">');}
}
while((m=re.exec(result))){handle(m[0]);}
if(out.length===0){
  var re2=/<(?:img|amp-img)[^>]*src="([^"]*biccam\.com\/chapters\/[^"]+)"[^>]*>/g;
  var m2;
  while((m2=re2.exec(result))){if(!seen[m2[1]]){seen[m2[1]]=1;out.push('<img src="'+m2[1]+'">');}}
}
return out.join('\n');})()
